// Exercise component-wise tan; avoid inputs near odd multiples of pi/2.
{
  auto safe_angle = [](double x){
    // Map to (-pi/2, pi/2) and push away from singularities by epsilon.
    double pi = std::acos(-1.0);
    double a = std::fmod(x, pi); // now in (-pi, pi)
    if (a >  pi/2) a -= pi; if (a < -pi/2) a += pi; // now ~(-pi/2, pi/2)
    double eps = 1e-6;
    if (a >  pi/2 - eps) a =  pi/2 - eps;
    if (a < -pi/2 + eps) a = -pi/2 + eps;
    return a;
  };
  linalg::vec<double, 3> v(safe_angle(*FUZZ_PARAM(double)), safe_angle(*FUZZ_PARAM(double)), safe_angle(*FUZZ_PARAM(double)));
  auto rv = linalg::tan(v);
  double s = safe_angle(*FUZZ_PARAM(double));
  auto rs = linalg::tan(s);
  (void)rv; (void)rs;
  // Validation: Inputs constrained away from tan singularities for numerical stability.
}

